// Puts upcoming payments, price changes and cash together per company. All amounts come from Aggregate, not the AI.
const parse = (item, key) => {
  const text = (item.json.content ?? []).map((c) => (typeof c.text === 'string' ? c.text : JSON.stringify(c.text))).join('\n');
  const at = text.indexOf('{"' + key + '"');
  if (at < 0) throw new Error('Aggregate did not return ' + key + ': ' + text.slice(0, 300));
  return { note: text.slice(0, at).trim(), data: JSON.parse(text.slice(at)) };
};
const money = (amount, currency, signed = false) => {
  const n = Number(amount);
  const v = Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const body = currency === 'USD' ? '$' + v : v + ' ' + currency;
  return signed ? (n < 0 ? '-' : '+') + body : body;
};
const s = $('Settings').first().json;
const up = parse($('Get upcoming').first(), 'days');
const rec = parse($('Get price changes').first(), 'recurring');
const ov = parse($('Get overview').first(), 'as_of');
const end = new Date(Date.now() + s.days * 86400000).toISOString().slice(0, 10);
const items = (up.data.items ?? []).filter((u) => Number(u.amount.amount) < 0 && Math.abs(Number(u.amount.amount)) >= s.minAmount);
const changed = (rec.data.recurring ?? []).filter((r) => r.next_due && r.next_due <= end);
const names = [...new Set([...items.map((u) => u.company), ...changed.map((r) => r.company)])];
const summary = names.map((company) => {
  const mine = items.filter((u) => u.company === company).sort((a, b) => a.date.localeCompare(b.date));
  const cents = {};
  for (const u of mine) cents[u.amount.currency] = (cents[u.amount.currency] ?? 0) + Math.round(Math.abs(Number(u.amount.amount)) * 100);
  const cash = (ov.data.companies ?? []).find((c) => c.company === company)?.cash;
  return {
    company,
    cash: cash ? money(cash.amount, cash.currency) : 'unknown',
    total_due: Object.entries(cents).map(([cur, v]) => money(v / 100, cur)).join(' + ') || 'none',
    items: mine.map((u) => ({ date: u.date, what: u.what, kind: u.kind, amount: money(u.amount.amount, u.amount.currency), estimated: u.confidence !== 'scheduled' })),
    price_changes: changed.filter((r) => r.company === company).map((r) => {
      const last = (r.changes ?? []).at(-1);
      return { who: r.counterparty, now: money(r.amount.amount, r.amount.currency), next_due: r.next_due, change: last ? `${last.kind === 'price_increase' ? 'up' : 'changed'} from ${money(last.from.amount, last.from.currency)} on ${last.date}` : 'changed' };
    }),
  };
});
const caveat = /missing for [^.]*\./.exec(up.note)?.[0] ?? '';
return [{ json: { summary, count: items.length + changed.length, days: s.days, caveat, as_text: JSON.stringify(summary) } }];

