// Builds the email. Every line comes from Aggregate; the AI adds only the short note at the top, and only if it uses no new figures.
const { summary, days, caveat } = $('Build summary').first().json;
const raw = ($json.output?.note ?? '').trim();
const allowed = JSON.stringify(summary);
const figures = raw.match(/\d[\d,]*(\.\d+)?/g) ?? [];
const note = figures.every((f) => allowed.includes(f)) ? raw : '';
const lines = [];
if (note) lines.push(note, '');
for (const co of summary) {
  lines.push(`${co.company}: ${co.total_due} due in the next ${days} days, cash ${co.cash}`);
  for (const i of co.items) lines.push(`  ${i.date}  ${i.what}  ${i.amount}${i.estimated ? ' (estimated)' : ''}`);
  for (const p of co.price_changes) lines.push(`  Price change: ${p.who} is now ${p.now}, ${p.change}; next charge ${p.next_due}`);
  lines.push('');
}
if (caveat) lines.push(`Note from Aggregate: minimum payments are ${caveat}`);
lines.push('From your books in Aggregate. Nothing here has been paid; Aggregate can\'t move money.');
return [{ json: { subject: `Bills and renewals, next ${days} days`, message: lines.join('\n') } }];
